lemma tendsto_dist_add_dist_nhds_zero
    {ι : Type*} {X : Type*} [PseudoMetricSpace X] {l : Filter ι}
    {xn yn : ι → X} {x y : X}
    (hx : Tendsto xn l (𝓝 x)) (hy : Tendsto yn l (𝓝 y)) :
    Tendsto (fun i ↦ dist (xn i) x + dist (yn i) y) l (𝓝 0)

lemma HasThinCover.toReal_volume_hSlice_le {P : Set (Fin 2 → ℝ)} {v ε u : ℝ}
    (h : HasThinCover P v ε) (hu : |u - v| ≤ ε) :
    (volume (hSlice P u)).toReal ≤ 100 * ε

lemma tendsto_stripPoint {ι : Type*} {l : Filter ι} {xn : ι → Fin n → ℝ} {x : Fin n → ℝ}
    (h : ℝ) (hx : Tendsto xn l (𝓝 x)) :
    Tendsto (fun i => stripPoint (xn i) h) l (𝓝 (stripPoint x h))

private lemma staircase_mem_band {K : ℕ} (hK : 0 < K) {h v ε y : ℝ} (hh0 : 0 < h)
    (hKh : (K : ℝ) * h = 2 * ε) (hy : |y - v| ≤ ε) :
    let m := min ⌊(y - (v - ε)) / h⌋₊ (K - 1)
    m < K ∧ v - ε + h * (m : ℝ) ≤ y ∧ y ≤ v - ε + h * ((m : ℝ) + 1)

private lemma fibreSegment_eq_fan (x₁ x₂ : Fin n → ℝ) (v : ℝ) :
    fibreSegment x₁ x₂ =
      fan (fun i => x₁ i + v * (x₂ i - x₁ i)) (fun i => x₂ i - x₁ i) 0 v

private lemma isOpen_setOf_hasThinCover (v ε : ℝ) :
    IsOpen {K : NonemptyCompacts (Fin (n + 1) → ℝ) |
      HasThinCover (K : Set (Fin (n + 1) → ℝ)) v ε}

lemma HasThinCover.toReal_volume_hSlice_le {P : Set (Fin (n+1) → ℝ)} {v ε u : ℝ}
    (h : HasThinCover P v ε) (hu : |u - v| ≤ ε) :
    (volume (hSlice P u)).toReal ≤ 100 * 4 ^ n * ε

theorem ae_hausdorffMeasure_vertical_slice_lt_top {A : Set (EuclideanSpace ℝ (Fin 2))}
    {s : ℝ} (h1 : 1 ≤ s) (hs : μH[s] A < ∞) :
    ∀ᵐ c : ℝ, μH[s - 1] (A ∩ {p | p 0 = c}) < ∞

private lemma isOpen_setOf_segment_subset {U : Set (EuclideanSpace ℝ (Fin 2))}
    (hU : IsOpen U) (q : ℝ) :
    IsOpen {p : EuclideanSpace ℝ (Fin 2) |
      ∀ t ∈ Icc (0 : ℝ) (1 / 2 : ℝ), pt (q + t) (p 0 * t + p 1) ∈ U}

private lemma exists_dualSet_hausdorffMeasure_ne_zero {B G : Set (EuclideanSpace ℝ (Fin 2))}
    (hB : IsKakeya B) (hBG : B ⊆ G) :
    ∃ q : ℚ, μH[(1 : ℝ)] (dualSet G (q : ℝ)) ≠ 0

private lemma hausdorffMeasure_eq_top_of_isGδ {B G : Set (EuclideanSpace ℝ (Fin 2))}
    (hB : IsKakeya B) (hBG : B ⊆ G) (hG : IsGδ G) {α : ℝ≥0} (hα1 : 1 ≤ α)
    (hα2 : (α : ℝ≥0∞) < 2) : μH[(α : ℝ)] G = ∞

@[simp] lemma reflectScale_apply (i : Fin (n + 1)) (u : Fin (n + 1) → ℝ) (j : Fin (n + 1)) :
    reflectScale i u j =
      if j = i then u (Fin.last n) else 2 * u (Equiv.swap i (Fin.last n) j)
